raw.css:
:root {
  --color-primary: #9b2c1c;
  --color-primary-dark: #6b1f13;
  --color-accent: #c8a882;
  --color-accent-light: #e8d5c4;
  --color-accent-on-dark: #f0e0d0;
  --color-bg: #faf8f5;
  --color-text: #2a2a2a;
  --color-text-light: #666;
  --color-border: #e0d5cc;
  --color-success: #4a7c59;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: Verdana, Arial, sans-serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
}

body {
  font-family: var(--font-serif);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
}

heading {
  font-family: var(--font-serif);
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.2;
}

h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 700;
  line-height: 1.3;
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  font-weight: 600;
}

p {
  margin-bottom: var(--spacing-md);
  color: var(--color-text-light);
  font-size: 1rem;
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.site-header {
  background-color: white;
  border-bottom: 2px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--spacing-md);
  padding-bottom: var(--spacing-md);
}

.logo {
  font-family: "Brush Script MT", "Segoe Script", cursive;
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 400;
  color: var(--color-primary);
  text-decoration: none;
  white-space: nowrap;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.1);
  transition: var(--transition);
}

.logo:hover {
  color: var(--color-primary-dark);
  text-shadow: 3px 3px 6px rgba(0, 0, 0, 0.15);
}

.logo:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
  border-radius: 4px;
}

.main-nav {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
  justify-content: flex-end;
}

.main-nav a {
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-text);
  text-decoration: none;
  padding-bottom: 4px;
  border-bottom: 2px solid transparent;
  transition: var(--transition);
}

.main-nav a:hover {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
  text-decoration: none;
}

.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-lg) var(--spacing-md);
  margin-top: var(--spacing-xl);
}

.site-footer .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-lg);
  align-items: start;
}

.site-footer a {
  color: var(--color-accent-light);
}

.site-footer a:hover {
  color: white;
}

.copyright {
  grid-column: 1 / -1;
  text-align: center;
  font-size: 0.9rem;
  color: var(--color-accent-on-dark);
  border-top: 1px solid rgba(255, 255, 255, 0.2);
  padding-top: var(--spacing-md);
  margin: var(--spacing-md) 0 0 0;
}

button, .btn {
  background-color: var(--color-primary);
  color: white;
  border: none;
  border-radius: 4px;
  padding: 12px 24px;
  font-size: 1rem;
  font-family: var(--font-sans);
  font-weight: 600;
  cursor: pointer;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  text-decoration: none;
}

button:hover, .btn:hover {
  background-color: var(--color-primary-dark);
}

button:focus, .btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active {
  transform: scale(0.98);
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
  color: var(--color-text);
}

input, textarea, select {
  width: 100%;
  padding: 12px;
  margin-bottom: var(--spacing-md);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  background-color: white;
  color: var(--color-text);
  min-height: 44px;
  transition: var(--transition);
}

textarea {
  min-height: 120px;
  resize: vertical;
}

input:focus, textarea:focus, select:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-color: var(--color-primary);
}

form {
  display: flex;
  flex-direction: column;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-md);
}

.form-row > * {
  margin-bottom: 0;
}

.card {
  background-color: white;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-md);
  transition: var(--transition);
}

.card:hover {
  box-shadow: 0 4px 12px rgba(155, 44, 28, 0.1);
  transform: translateY(-2px);
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-lg);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-lg);
}

.section {
  padding: var(--spacing-xl) 0;
}

.section-title {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

@media (max-width: 600px) {
  .site-header .container {
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .main-nav {
    gap: var(--spacing-sm);
    justify-content: center;
  }

  .main-nav a {
    font-size: 0.9rem;
  }

  .logo {
    font-size: 1.3rem;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.4rem;
  }

  h3 {
    font-size: 1.1rem;
  }

  .grid-2, .grid-3 {
    grid-template-columns: 1fr;
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .site-footer .container {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  button, .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .site-header .container {
    padding-top: var(--spacing-lg);
    padding-bottom: var(--spacing-lg);
  }

  .main-nav {
    gap: var(--spacing-lg);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

pages.css:
.hero {
  background: linear-gradient(135deg, rgba(155, 44, 28, 0.15) 0%, rgba(200, 168, 130, 0.1) 100%), url('https://images.unsplash.com/photo-1504674900967-a364ba7fadad?w=1200&h=600&fit=crop') center/cover no-repeat;
  padding: var(--spacing-xl) var(--spacing-md);
  text-align: center;
  color: var(--color-text);
}

.hero .container {
  padding: var(--spacing-xl) 0;
}

.hero h1 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.hero-tagline {
  font-size: clamp(1.2rem, 3vw, 1.5rem);
  color: var(--color-primary);
  font-weight: 600;
  margin-bottom: var(--spacing-md);
  font-family: var(--font-serif);
}

.hero-description {
  font-size: 1rem;
  color: var(--color-text-light);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
  line-height: 1.8;
}

.btn-primary {
  background-color: var(--color-primary);
  color: white;
}

.btn-primary:hover {
  background-color: var(--color-primary-dark);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
  padding: 10px 22px;
}

.btn-secondary:hover {
  background-color: var(--color-primary);
  color: white;
}

.signature-dishes {
  padding: var(--spacing-xl) var(--spacing-md);
}

.dish-card {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.dish-image {
  width: 100%;
  height: 250px;
  object-fit: cover;
  border-radius: 6px;
  margin-bottom: var(--spacing-md);
  display: block;
}

.dish-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.dish-card p {
  flex-grow: 1;
  margin-bottom: var(--spacing-sm);
}

.dish-price {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: 0;
}

.testimonial {
  padding: var(--spacing-xl) var(--spacing-md);
}

.testimonial-text {
  font-size: 1.1rem;
  line-height: 1.8;
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
  color: var(--color-text);
}

.testimonial-text p {
  font-style: italic;
  margin-bottom: var(--spacing-md);
  color: var(--color-text);
}

.testimonial-author {
  display: block;
  font-style: normal;
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-top: var(--spacing-md);
}

.cta {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: white;
  border-top: 2px solid var(--color-border);
  border-bottom: 2px solid var(--color-border);
}

.cta-text {
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
  text-align: center;
  font-size: 1rem;
  line-height: 1.8;
  margin-bottom: var(--spacing-lg);
}

.cta-buttons {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
}

.cta-buttons .btn {
  min-width: 200px;
}

@media (max-width: 600px) {
  .hero {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .hero .container {
    padding: var(--spacing-lg) 0;
  }

  .hero-tagline {
    font-size: 1.1rem;
  }

  .hero-description {
    font-size: 0.95rem;
    margin-bottom: var(--spacing-md);
  }

  .signature-dishes {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .dish-image {
    height: 200px;
  }

  .testimonial {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .testimonial-text {
    font-size: 1rem;
  }

  .cta {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .cta-buttons {
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .cta-buttons .btn {
    width: 100%;
    min-width: auto;
  }
}

@media (min-width: 601px) {
  .hero {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .hero .container {
    padding: var(--spacing-xl) 0;
  }

  .cta-buttons {
    gap: var(--spacing-lg);
  }
}

.menu-intro {
  padding: var(--spacing-xl) 0;
  background-color: white;
  border-bottom: 2px solid var(--color-border);
}

.menu-intro p {
  text-align: center;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
  font-size: 1.1rem;
}

.menu-section {
  padding: var(--spacing-xl) 0;
  border-bottom: 1px solid var(--color-border);
}

.menu-section:nth-child(odd) {
  background-color: rgba(232, 213, 196, 0.15);
}

.menu-section-intro {
  text-align: center;
  font-size: 1rem;
  font-style: italic;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-lg);
}

.menu-item {
  background-color: white;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  padding: var(--spacing-md);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.menu-item:hover {
  box-shadow: 0 4px 12px rgba(155, 44, 28, 0.12);
  transform: translateY(-2px);
  border-color: var(--color-primary);
}

.menu-item h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
  font-size: 1.1rem;
}

.menu-description {
  flex-grow: 1;
  font-size: 0.95rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-sm);
  line-height: 1.5;
}

.menu-price {
  font-weight: 700;
  color: var(--color-primary);
  font-size: 1.1rem;
  margin-bottom: 0;
}

.menu-cta {
  padding: var(--spacing-xl) 0;
  background-color: var(--color-accent-light);
  text-align: center;
}

.menu-cta h2 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.menu-cta p {
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
  font-size: 1rem;
}

@media (max-width: 600px) {
  .menu-intro {
    padding: var(--spacing-lg) 0;
  }

  .menu-section {
    padding: var(--spacing-lg) 0;
  }

  .menu-item h3 {
    font-size: 1rem;
  }

  .menu-description {
    font-size: 0.9rem;
  }

  .menu-price {
    font-size: 1rem;
  }

  .menu-cta {
    padding: var(--spacing-lg) 0;
  }

  .menu-cta .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .menu-item {
    padding: var(--spacing-lg);
  }
}

.gallery-hero {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xl) 0;
}

.gallery-intro {
  font-size: 1.125rem;
  color: var(--color-text);
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.gallery-grid-section {
  padding: var(--spacing-xl) 0;
}

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-lg);
}

.gallery-item {
  position: relative;
  overflow: hidden;
  border-radius: 8px;
  background-color: white;
  border: 1px solid var(--color-border);
  transition: var(--transition);
}

.gallery-item:hover {
  box-shadow: 0 8px 24px rgba(155, 44, 28, 0.15);
  transform: translateY(-4px);
}

.gallery-item figure {
  margin: 0;
  position: relative;
  overflow: hidden;
  height: 300px;
}

.gallery-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: var(--transition);
}

.gallery-item:hover img {
  transform: scale(1.05);
}

.gallery-item figcaption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: linear-gradient(to top, rgba(107, 31, 19, 0.95), transparent);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-md) var(--spacing-sm) var(--spacing-sm);
  font-weight: 600;
  font-size: 1rem;
  transform: translateY(20px);
  transition: var(--transition);
}

.gallery-item:hover figcaption {
  transform: translateY(0);
}

.gallery-cta {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.gallery-cta h2 {
  color: var(--color-accent-on-dark);
}

.gallery-cta p {
  color: var(--color-accent-light);
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
  font-size: 1.0625rem;
}

@media (max-width: 600px) {
  .gallery-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--spacing-md);
  }

  .gallery-item figure {
    height: 250px;
  }

  .gallery-intro {
    font-size: 1rem;
  }

  .gallery-cta {
    padding: var(--spacing-lg) 0;
  }

  .gallery-cta h2 {
    font-size: 1.5rem;
  }

  .gallery-cta p {
    font-size: 1rem;
  }
}

@media (min-width: 601px) and (max-width: 900px) {
  .gallery-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.about-hero {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xl) 0;
}

.about-intro {
  font-size: 1.15rem;
  color: var(--color-text);
  line-height: 1.8;
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.about-story {
  padding: var(--spacing-xl) 0;
}

.about-story-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: center;
}

.about-narrative {
  font-size: 1.05rem;
  line-height: 1.8;
}

.about-narrative p {
  margin-bottom: var(--spacing-md);
  color: var(--color-text-light);
}

.about-narrative p:last-child {
  margin-bottom: 0;
}

.about-image {
  width: 100%;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 8px 20px rgba(155, 44, 28, 0.15);
}

.about-image img {
  width: 100%;
  height: 400px;
  object-fit: cover;
  display: block;
}

.about-pillars {
  background-color: var(--color-bg);
  padding: var(--spacing-xl) 0;
}

.pillar-card {
  background-color: white;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  transition: var(--transition);
  text-align: center;
}

.pillar-card:hover {
  box-shadow: 0 8px 16px rgba(155, 44, 28, 0.1);
  transform: translateY(-4px);
}

.pillar-card h3 {
  color: var(--color-primary);
  margin-bottom: var(--spacing-md);
}

.pillar-card p {
  color: var(--color-text-light);
  font-size: 0.95rem;
  margin-bottom: 0;
}

.about-experience {
  padding: var(--spacing-xl) 0;
  background-color: white;
}

.about-experience .container {
  max-width: 700px;
}

.about-experience h2 {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.about-experience p {
  text-align: center;
  font-size: 1.05rem;
  line-height: 1.8;
  margin-bottom: var(--spacing-md);
}

.about-experience .btn {
  display: inline-block;
  margin: var(--spacing-lg) auto 0;
}

.about-experience .container {
  display: flex;
  flex-direction: column;
  align-items: center;
}

@media (max-width: 600px) {
  .about-hero {
    padding: var(--spacing-lg) 0;
  }

  .about-intro {
    font-size: 1rem;
  }

  .about-story-content {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .about-image img {
    height: 300px;
  }

  .about-narrative {
    font-size: 1rem;
  }

  .pillar-card {
    padding: var(--spacing-md);
  }

  .about-pillars {
    padding: var(--spacing-lg) 0;
  }

  .about-experience {
    padding: var(--spacing-lg) 0;
  }

  .about-experience p {
    font-size: 1rem;
  }
}

@media (min-width: 601px) {
  .about-hero {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .about-story {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .about-pillars {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .about-experience {
    padding: var(--spacing-xl) var(--spacing-md);
  }
}

.contact-hero {
  background-color: var(--color-accent-light);
  padding: var(--spacing-lg) 0;
  text-align: center;
}

.contact-intro {
  font-size: 1.1rem;
  color: var(--color-text);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.contact-main {
  padding: var(--spacing-xl) 0;
}

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: start;
}

.contact-form-wrapper {
  background-color: white;
  padding: var(--spacing-lg);
  border: 1px solid var(--color-border);
  border-radius: 8px;
}

.contact-form-wrapper h2 {
  margin-bottom: var(--spacing-lg);
  color: var(--color-primary-dark);
}

.contact-form {
  display: flex;
  flex-direction: column;
}

.contact-form input,
.contact-form select,
.contact-form textarea {
  font-size: 1rem;
}

.contact-btn {
  margin-top: var(--spacing-md);
  width: 100%;
}

.contact-info-wrapper h2 {
  margin-bottom: var(--spacing-lg);
  color: var(--color-primary-dark);
}

.contact-info-section {
  margin-bottom: var(--spacing-lg);
  padding-bottom: var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
}

.contact-info-section:last-child {
  border-bottom: none;
  padding-bottom: 0;
  margin-bottom: 0;
}

.contact-info-section h3 {
  color: var(--color-primary);
  margin-bottom: var(--spacing-sm);
}

.contact-info-section p {
  margin-bottom: 0;
  color: var(--color-text-light);
}

.contact-info-section a {
  color: var(--color-primary);
  font-weight: 600;
}

.contact-hours {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.contact-hours-row {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: var(--spacing-md);
  align-items: start;
}

.contact-day {
  font-weight: 600;
  color: var(--color-text);
}

.contact-time {
  color: var(--color-text-light);
}

.contact-closed .contact-time {
  color: var(--color-primary);
  font-weight: 600;
}

.contact-map {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.contact-map h2 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.contact-map p {
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
}

.map-placeholder {
  width: 100%;
  max-width: 800px;
  height: 400px;
  margin: 0 auto;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 4px 12px rgba(155, 44, 28, 0.1);
}

.map-placeholder img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

@media (max-width: 600px) {
  .contact-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .contact-form-wrapper {
    padding: var(--spacing-md);
  }

  .contact-hours-row {
    grid-template-columns: 1fr;
    gap: var(--spacing-xs);
  }

  .contact-day {
    display: block;
    margin-bottom: var(--spacing-xs);
  }

  .map-placeholder {
    height: 300px;
  }

  .contact-main,
  .contact-map {
    padding: var(--spacing-lg) 0;
  }

  .contact-hero {
    padding: var(--spacing-md) 0;
  }

  .contact-intro {
    font-size: 1rem;
  }
}

@media (min-width: 601px) {
  .form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-md);
  }

  .form-row > * {
    margin-bottom: 0;
  }
}

final.css:
:root {
  --color-primary: #9b2c1c;
  --color-primary-dark: #6b1f13;
  --color-accent: #c8a882;
  --color-accent-light: #e8d5c4;
  --color-accent-on-dark: #f0e0d0;
  --color-bg: #faf8f5;
  --color-text: #2a2a2a;
  --color-text-light: #666;
  --color-text-on-dark: #a8a8a8;
  --color-border: #e0d5cc;
  --color-success: #4a7c59;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: Verdana, Arial, sans-serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
}

body {
  font-family: var(--font-serif);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
}

heading {
  font-family: var(--font-serif);
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

h1 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 1.2;
}

h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 700;
  line-height: 1.3;
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  font-weight: 600;
}

p {
  margin-bottom: var(--spacing-md);
  color: var(--color-text-light);
  font-size: 1rem;
}

a {
  color: var(--color-primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.site-header {
  background-color: white;
  border-bottom: 2px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--spacing-md);
  padding-bottom: var(--spacing-md);
}

.logo {
  font-family: "Brush Script MT", "Segoe Script", cursive;
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 400;
  color: var(--color-primary);
  text-decoration: none;
  white-space: nowrap;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.1);
  transition: var(--transition);
}

.logo:hover {
  color: var(--color-primary-dark);
  text-shadow: 3px 3px 6px rgba(0, 0, 0, 0.15);
}

.logo:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
  border-radius: 4px;
}

.main-nav {
  display: flex;
  gap: var(--spacing-md);
  flex-wrap: wrap;
  justify-content: flex-end;
}

.main-nav a {
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-text);
  text-decoration: none;
  padding-bottom: 4px;
  border-bottom: 2px solid transparent;
  transition: var(--transition);
}

.main-nav a:hover {
  color: var(--color-primary);
  border-bottom-color: var(--color-primary);
  text-decoration: none;
}

.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-lg) var(--spacing-md);
  margin-top: var(--spacing-xl);
}

.site-footer p {
  color: var(--color-text-on-dark);
}

.site-footer .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-lg);
  align-items: start;
}

.site-footer a {
  color: var(--color-accent-light);
}

.site-footer a:hover {
  color: white;
}

.copyright {
  grid-column: 1 / -1;
  text-align: center;
  font-size: 0.9rem;
  color: var(--color-accent-on-dark);
  border-top: 1px solid rgba(255, 255, 255, 0.2);
  padding-top: var(--spacing-md);
  margin: var(--spacing-md) 0 0 0;
}

button, .btn {
  background-color: var(--color-primary);
  color: white;
  border: none;
  border-radius: 4px;
  padding: 12px 24px;
  font-size: 1rem;
  font-family: var(--font-sans);
  font-weight: 600;
  cursor: pointer;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  text-decoration: none;
}

button:hover, .btn:hover {
  background-color: var(--color-primary-dark);
}

button:focus, .btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active {
  transform: scale(0.98);
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
  color: var(--color-text);
}

input, textarea, select {
  width: 100%;
  padding: 12px;
  margin-bottom: var(--spacing-md);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  background-color: white;
  color: var(--color-text);
  min-height: 44px;
  transition: var(--transition);
}

textarea {
  min-height: 120px;
  resize: vertical;
}

input:focus, textarea:focus, select:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-color: var(--color-primary);
}

form {
  display: flex;
  flex-direction: column;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-md);
}

.form-row > * {
  margin-bottom: 0;
}

.card {
  background-color: white;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-md);
  transition: var(--transition);
}

.card:hover {
  box-shadow: 0 4px 12px rgba(155, 44, 28, 0.1);
  transform: translateY(-2px);
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-lg);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-lg);
}

.section {
  padding: var(--spacing-xl) 0;
}

.section-title {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

@media (max-width: 600px) {
  .site-header .container {
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .main-nav {
    gap: var(--spacing-sm);
    justify-content: center;
  }

  .main-nav a {
    font-size: 0.9rem;
  }

  .logo {
    font-size: 1.3rem;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.4rem;
  }

  h3 {
    font-size: 1.1rem;
  }

  .grid-2, .grid-3 {
    grid-template-columns: 1fr;
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .site-footer .container {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  button, .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .site-header .container {
    padding-top: var(--spacing-lg);
    padding-bottom: var(--spacing-lg);
  }

  .main-nav {
    gap: var(--spacing-lg);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

pages.css:
.hero {
  background: linear-gradient(135deg, rgba(155, 44, 28, 0.15) 0%, rgba(200, 168, 130, 0.1) 100%), url('https://images.unsplash.com/photo-1504674900967-a364ba7fadad?w=1200&h=600&fit=crop') center/cover no-repeat;
  padding: var(--spacing-xl) var(--spacing-md);
  text-align: center;
  color: var(--color-text);
}

.hero .container {
  padding: var(--spacing-xl) 0;
}

.hero h1 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.hero-tagline {
  font-size: clamp(1.2rem, 3vw, 1.5rem);
  color: var(--color-primary);
  font-weight: 600;
  margin-bottom: var(--spacing-md);
  font-family: var(--font-serif);
}

.hero-description {
  font-size: 1rem;
  color: var(--color-text-light);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
  line-height: 1.8;
}

.btn-primary {
  background-color: var(--color-primary);
  color: white;
}

.btn-primary:hover {
  background-color: var(--color-primary-dark);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
  padding: 10px 22px;
}

.btn-secondary:hover {
  background-color: var(--color-primary);
  color: white;
}

.signature-dishes {
  padding: var(--spacing-xl) var(--spacing-md);
}

.dish-card {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.dish-image {
  width: 100%;
  height: 250px;
  object-fit: cover;
  border-radius: 6px;
  margin-bottom: var(--spacing-md);
  display: block;
}

.dish-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.dish-card p {
  flex-grow: 1;
  margin-bottom: var(--spacing-sm);
}

.dish-price {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: 0;
}

.testimonial {
  padding: var(--spacing-xl) var(--spacing-md);
}

.testimonial-text {
  font-size: 1.1rem;
  line-height: 1.8;
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
  color: var(--color-text);
}

.testimonial-text p {
  font-style: italic;
  margin-bottom: var(--spacing-md);
  color: var(--color-text);
}

.testimonial-author {
  display: block;
  font-style: normal;
  font-weight: 600;
  color: var(--color-primary-dark);
  margin-top: var(--spacing-md);
}

.cta {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: white;
  border-top: 2px solid var(--color-border);
  border-bottom: 2px solid var(--color-border);
}

.cta-text {
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
  text-align: center;
  font-size: 1rem;
  line-height: 1.8;
  margin-bottom: var(--spacing-lg);
}

.cta-buttons {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
}

.cta-buttons .btn {
  min-width: 200px;
}

@media (max-width: 600px) {
  .hero {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .hero .container {
    padding: var(--spacing-lg) 0;
  }

  .hero-tagline {
    font-size: 1.1rem;
  }

  .hero-description {
    font-size: 0.95rem;
    margin-bottom: var(--spacing-md);
  }

  .signature-dishes {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .dish-image {
    height: 200px;
  }

  .testimonial {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .testimonial-text {
    font-size: 1rem;
  }

  .cta {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .cta-buttons {
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  .cta-buttons .btn {
    width: 100%;
    min-width: auto;
  }
}

@media (min-width: 601px) {
  .hero {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .hero .container {
    padding: var(--spacing-xl) 0;
  }

  .cta-buttons {
    gap: var(--spacing-lg);
  }
}

.menu-intro {
  padding: var(--spacing-xl) 0;
  background-color: white;
  border-bottom: 2px solid var(--color-border);
}

.menu-intro p {
  text-align: center;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
  font-size: 1.1rem;
}

.menu-section {
  padding: var(--spacing-xl) 0;
  border-bottom: 1px solid var(--color-border);
}

.menu-section:nth-child(odd) {
  background-color: rgba(232, 213, 196, 0.15);
}

.menu-section-intro {
  text-align: center;
  font-size: 1rem;
  font-style: italic;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-lg);
}

.menu-item {
  background-color: white;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  padding: var(--spacing-md);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.menu-item:hover {
  box-shadow: 0 4px 12px rgba(155, 44, 28, 0.12);
  transform: translateY(-2px);
  border-color: var(--color-primary);
}

.menu-item h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
  font-size: 1.1rem;
}

.menu-description {
  flex-grow: 1;
  font-size: 0.95rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-sm);
  line-height: 1.5;
}

.menu-price {
  font-weight: 700;
  color: var(--color-primary);
  font-size: 1.1rem;
  margin-bottom: 0;
}

.menu-cta {
  padding: var(--spacing-xl) 0;
  background-color: var(--color-accent-light);
  text-align: center;
}

.menu-cta p {
  color: #5c5c5c;
}

.menu-cta h2 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.menu-cta p {
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
  font-size: 1rem;
}

@media (max-width: 600px) {
  .menu-intro {
    padding: var(--spacing-lg) 0;
  }

  .menu-section {
    padding: var(--spacing-lg) 0;
  }

  .menu-item h3 {
    font-size: 1rem;
  }

  .menu-description {
    font-size: 0.9rem;
  }

  .menu-price {
    font-size: 1rem;
  }

  .menu-cta {
    padding: var(--spacing-lg) 0;
  }

  .menu-cta .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .menu-item {
    padding: var(--spacing-lg);
  }
}

.gallery-hero {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xl) 0;
}

.gallery-intro {
  font-size: 1.125rem;
  color: var(--color-text);
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.gallery-grid-section {
  padding: var(--spacing-xl) 0;
}

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-lg);
}

.gallery-item {
  position: relative;
  overflow: hidden;
  border-radius: 8px;
  background-color: white;
  border: 1px solid var(--color-border);
  transition: var(--transition);
}

.gallery-item:hover {
  box-shadow: 0 8px 24px rgba(155, 44, 28, 0.15);
  transform: translateY(-4px);
}

.gallery-item figure {
  margin: 0;
  position: relative;
  overflow: hidden;
  height: 300px;
}

.gallery-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: var(--transition);
}

.gallery-item:hover img {
  transform: scale(1.05);
}

.gallery-item figcaption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: linear-gradient(to top, rgba(107, 31, 19, 0.95), transparent);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-md) var(--spacing-sm) var(--spacing-sm);
  font-weight: 600;
  font-size: 1rem;
  transform: translateY(20px);
  transition: var(--transition);
}

.gallery-item:hover figcaption {
  transform: translateY(0);
}

.gallery-cta {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.gallery-cta h2 {
  color: var(--color-accent-on-dark);
}

.gallery-cta p {
  color: var(--color-accent-light);
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
  font-size: 1.0625rem;
}

@media (max-width: 600px) {
  .gallery-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: var(--spacing-md);
  }

  .gallery-item figure {
    height: 250px;
  }

  .gallery-intro {
    font-size: 1rem;
  }

  .gallery-cta {
    padding: var(--spacing-lg) 0;
  }

  .gallery-cta h2 {
    font-size: 1.5rem;
  }

  .gallery-cta p {
    font-size: 1rem;
  }
}

@media (min-width: 601px) and (max-width: 900px) {
  .gallery-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.about-hero {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xl) 0;
}

.about-intro {
  font-size: 1.15rem;
  color: var(--color-text);
  line-height: 1.8;
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.about-story {
  padding: var(--spacing-xl) 0;
}

.about-story-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: center;
}

.about-narrative {
  font-size: 1.05rem;
  line-height: 1.8;
}

.about-narrative p {
  margin-bottom: var(--spacing-md);
  color: var(--color-text-light);
}

.about-narrative p:last-child {
  margin-bottom: 0;
}

.about-image {
  width: 100%;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 8px 20px rgba(155, 44, 28, 0.15);
}

.about-image img {
  width: 100%;
  height: 400px;
  object-fit: cover;
  display: block;
}

.about-pillars {
  background-color: var(--color-bg);
  padding: var(--spacing-xl) 0;
}

.pillar-card {
  background-color: white;
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  transition: var(--transition);
  text-align: center;
}

.pillar-card:hover {
  box-shadow: 0 8px 16px rgba(155, 44, 28, 0.1);
  transform: translateY(-4px);
}

.pillar-card h3 {
  color: var(--color-primary);
  margin-bottom: var(--spacing-md);
}

.pillar-card p {
  color: var(--color-text-light);
  font-size: 0.95rem;
  margin-bottom: 0;
}

.about-experience {
  padding: var(--spacing-xl) 0;
  background-color: white;
}

.about-experience .container {
  max-width: 700px;
}

.about-experience h2 {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.about-experience p {
  text-align: center;
  font-size: 1.05rem;
  line-height: 1.8;
  margin-bottom: var(--spacing-md);
}

.about-experience .btn {
  display: inline-block;
  margin: var(--spacing-lg) auto 0;
}

.about-experience .container {
  display: flex;
  flex-direction: column;
  align-items: center;
}

@media (max-width: 600px) {
  .about-hero {
    padding: var(--spacing-lg) 0;
  }

  .about-intro {
    font-size: 1rem;
  }

  .about-story-content {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .about-image img {
    height: 300px;
  }

  .about-narrative {
    font-size: 1rem;
  }

  .pillar-card {
    padding: var(--spacing-md);
  }

  .about-pillars {
    padding: var(--spacing-lg) 0;
  }

  .about-experience {
    padding: var(--spacing-lg) 0;
  }

  .about-experience p {
    font-size: 1rem;
  }
}

@media (min-width: 601px) {
  .about-hero {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .about-story {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .about-pillars {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .about-experience {
    padding: var(--spacing-xl) var(--spacing-md);
  }
}

.contact-hero {
  background-color: var(--color-accent-light);
  padding: var(--spacing-lg) 0;
  text-align: center;
}

.contact-intro {
  font-size: 1.1rem;
  color: var(--color-text);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.contact-main {
  padding: var(--spacing-xl) 0;
}

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: start;
}

.contact-form-wrapper {
  background-color: white;
  padding: var(--spacing-lg);
  border: 1px solid var(--color-border);
  border-radius: 8px;
}

.contact-form-wrapper h2 {
  margin-bottom: var(--spacing-lg);
  color: var(--color-primary-dark);
}

.contact-form {
  display: flex;
  flex-direction: column;
}

.contact-form input,
.contact-form select,
.contact-form textarea {
  font-size: 1rem;
}

.contact-btn {
  margin-top: var(--spacing-md);
  width: 100%;
}

.contact-info-wrapper h2 {
  margin-bottom: var(--spacing-lg);
  color: var(--color-primary-dark);
}

.contact-info-section {
  margin-bottom: var(--spacing-lg);
  padding-bottom: var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
}

.contact-info-section:last-child {
  border-bottom: none;
  padding-bottom: 0;
  margin-bottom: 0;
}

.contact-info-section h3 {
  color: var(--color-primary);
  margin-bottom: var(--spacing-sm);
}

.contact-info-section p {
  margin-bottom: 0;
  color: var(--color-text-light);
}

.contact-info-section a {
  color: var(--color-primary);
  font-weight: 600;
}

.contact-hours {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.contact-hours-row {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: var(--spacing-md);
  align-items: start;
}

.contact-day {
  font-weight: 600;
  color: var(--color-text);
}

.contact-time {
  color: var(--color-text-light);
}

.contact-closed .contact-time {
  color: var(--color-primary);
  font-weight: 600;
}

.contact-map {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xl) 0;
  text-align: center;
}

.contact-map p {
  color: #5c5c5c;
}

.contact-map h2 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.contact-map p {
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: var(--spacing-lg);
}

.map-placeholder {
  width: 100%;
  max-width: 800px;
  height: 400px;
  margin: 0 auto;
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 4px 12px rgba(155, 44, 28, 0.1);
}

.map-placeholder img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

@media (max-width: 600px) {
  .contact-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .contact-form-wrapper {
    padding: var(--spacing-md);
  }

  .contact-hours-row {
    grid-template-columns: 1fr;
    gap: var(--spacing-xs);
  }

  .contact-day {
    display: block;
    margin-bottom: var(--spacing-xs);
  }

  .map-placeholder {
    height: 300px;
  }

  .contact-main,
  .contact-map {
    padding: var(--spacing-lg) 0;
  }

  .contact-hero {
    padding: var(--spacing-md) 0;
  }

  .contact-intro {
    font-size: 1rem;
  }
}

@media (min-width: 601px) {
  .form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--spacing-md);
  }

  .form-row > * {
    margin-bottom: 0;
  }
}
